@push('script')
<script>
    (() => {
        const container = document.getElementById('company-accounts');
        const add = document.getElementById('add-company-account');
        let index = {{ count($settings['company_accounts']) }};
        const template = (i) => `<div class="border rounded p-3 mb-3 company-account"><div class="row g-2"><div class="col-md-3"><input class="form-control" name="company_accounts[${i}][bank_name]" placeholder="{{ translate('bank_name') }}"></div><div class="col-md-3"><input class="form-control" name="company_accounts[${i}][account_name]" placeholder="{{ translate('account_name') }}"></div><div class="col-md-3"><input class="form-control" name="company_accounts[${i}][account_number]" placeholder="{{ translate('account_number') }}"></div><div class="col-md-3"><input class="form-control" name="company_accounts[${i}][iban]" placeholder="{{ translate('iban') }}"></div><div class="col-12"><input class="form-control" name="company_accounts[${i}][notes]" placeholder="{{ translate('notes') }}"></div></div><button type="button" class="btn btn-sm btn-link text-danger remove-company-account">{{ translate('remove') }}</button></div>`;
        add?.addEventListener('click', () => { container.insertAdjacentHTML('beforeend', template(index++)); });
        container?.addEventListener('click', (event) => { if (event.target.classList.contains('remove-company-account')) event.target.closest('.company-account').remove(); });
    })();
</script>
@endpush
